package main_test

import (
	"errors"
	"testing"

	operator "github.com/klever-io/klever-go/cmd/operator"
	"github.com/stretchr/testify/assert"
)

func TestEncodeInput(t *testing.T) {
	tests := []struct {
		name string
		args []string
		want string
		err  error
	}{
		{
			name: "Int Values Valid",
			args: []string{"i8:5", "i16:500", "i32:50000", "i64:5000000000"},
			want: "@05@01f4@0000c350@000000012a05f200",
			err:  nil,
		},
		{
			name: "UInt Values Valid",
			args: []string{"u8:5", "u16:500", "u32:50000", "u64:5000000000"},
			want: "@05@01f4@c350@012a05f200",
			err:  nil,
		},
		{
			name: "BigInt Values Valid",
			args: []string{"bi:5000", "n:500000", "BI:500000"},
			want: "@1388@07a120@07a120",
			err:  nil,
		},
		{
			name: "File Valid",
			args: []string{"wasm:../../kvm/test/adder/output/adder.wasm"},
			want: "@",
			err:  nil,
		},
		{
			name: "Valid kleversc.json",
			args: []string{"file:../../kvm/test/adder/output/adder.kleversc.json"},
			want: "@",
			err:  nil,
		},
		{
			name: "File Valid invalid path",
			args: []string{"file:../../kvm/test/adder/output/adder1.wasm"},
			want: "",
			err:  errors.New("invalid item to encode `file:../../kvm/test/adder/output/adder1.wasm`"),
		},
		{
			name: "Invalid kleversc.json",
			args: []string{"file:../../kvm/test/adder/output/wrong.kleversc.json"},
			want: "",
			err:  errors.New("invalid item to encode `file:../../kvm/test/adder/output/wrong.kleversc.json`"),
		},
		{
			name: "Number Values Valid",
			args: []string{"number:5", "number:-5", "Number:500", "Number:-500", "Number:500000", "Number:-500000", "Number:5000000000", "Number:-5000000000"},
			want: "@05@fb@01f4@fe0c@07a120@fff85ee0@012a05f200@fffffffed5fa0e00", // u8 i8 u16 i16 u32 i32 u64 i64
			err:  nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := operator.EncodeInput(tt.args)
			assert.Equal(t, tt.err, err)
			assert.Equal(t, tt.want, got)

		})
	}
}
